import { QueryClientProvider } from '@tanstack/react-query';
import type { ReactNode } from 'react';
import type { TestApiHandlers } from './testApiHandlers';
import { TrpcProvider } from './trpc';
import { useTestApiClients } from './useTestApiClients';

export interface TestApiProviderProps {
  readonly handlers: TestApiHandlers;
  readonly children: ReactNode;
}

/** The app's providers over a typed in-memory api, for route tests. */
export function TestApiProvider({ handlers, children }: TestApiProviderProps) {
  const { queryClient, trpcClient } = useTestApiClients(handlers);
  return (
    <QueryClientProvider client={queryClient}>
      <TrpcProvider trpcClient={trpcClient} queryClient={queryClient}>
        {children}
      </TrpcProvider>
    </QueryClientProvider>
  );
}
=== apps/web/src/api-client/useTestApiClients.ts
import type { AppRouter } from '@repo/api';
import type { QueryClient } from '@tanstack/react-query';
import { createTRPCClient, type TRPCClient } from '@trpc/client';
import { useState } from 'react';
import { handlerLink, type TestApiHandlers } from './testApiHandlers';
import { createQueryClient } from './trpc';

/** One query client and one handler-backed tRPC client for the life of a test render. */
export function useTestApiClients(handlers: TestApiHandlers): {
  readonly queryClient: QueryClient;
  readonly trpcClient: TRPCClient<AppRouter>;
} {
  const [clients] = useState(() => ({
    queryClient: createQueryClient(),
    trpcClient: createTRPCClient<AppRouter>({ links: [handlerLink(handlers)] }),
  }));
  return clients;
}
